<?php require __DIR__.'/guard.php'; ?>
<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Карточка клиента — ПрофиСпорт</title>
<style>
:root{--y:#f2c94c;--bg:#f5f5f3;--tx:#202124;--muted:#747a80;--line:#e3e3df;--green:#19964a;--red:#b93429;--page:1180px}*{box-sizing:border-box}body{margin:0;font:15px/1.45 system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;background:var(--bg);color:var(--tx)}a{color:inherit}.top{background:linear-gradient(135deg,#454b51,#2f3439);color:#fff;position:sticky;top:0;z-index:20}.topin{max-width:var(--page);margin:auto;min-height:64px;padding:0 14px;display:flex;align-items:center;justify-content:space-between;gap:12px}.brand{font-weight:900;font-size:21px}.brand i{font-style:normal;color:var(--y)}.back{color:#fff;text-decoration:none;background:#ffffff17;border:1px solid #ffffff26;padding:10px 13px;border-radius:10px}main{max-width:var(--page);margin:18px auto;padding:0 14px 70px}.hero,.panel,.mini{background:#fff;border:1px solid var(--line);border-radius:18px}.hero{padding:20px}.heroTop{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.hero h1{margin:0 0 4px;font-size:30px}.muted{color:var(--muted)}.status{display:inline-flex;padding:6px 9px;border-radius:999px;background:#eef0ed;font-size:12px;font-weight:800}.status.ok{background:#e7f6eb;color:#176f38}.metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin-top:16px}.metric{background:#f7f7f4;border-radius:13px;padding:12px;min-width:0}.metric b{display:block;font-size:22px}.metric span{color:var(--muted);font-size:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.panel{padding:18px;min-width:0}.panel.wide{grid-column:1/-1}.panel h2{margin:0 0 12px;font-size:21px}.rows{display:grid;gap:9px}.row{display:flex;justify-content:space-between;gap:14px;padding:10px 0;border-top:1px solid var(--line)}.row:first-child{border-top:0}.row .value{text-align:right;overflow-wrap:anywhere}.cards{display:grid;gap:10px}.card{border:1px solid var(--line);border-radius:14px;padding:13px;background:#fff}.card h3{margin:0 0 4px;font-size:16px}.meta{color:var(--muted);font-size:12px;overflow-wrap:anywhere}.chips{display:flex;gap:6px;flex-wrap:wrap;margin:8px 0}.chip{padding:5px 8px;border-radius:999px;background:#f1f2ef;font-size:12px}.chip.yellow{background:#fff2b8}.chip.green{background:#e7f6eb;color:#176f38}.chip.red{background:#fae8e5;color:#9e3127}.money{font-weight:900}.items{margin:8px 0 0;padding-left:18px}.items li{margin:4px 0}.timeline{display:grid;gap:5px;margin-top:8px}.timeline span{font-size:12px;color:var(--muted)}.empty{color:var(--muted);padding:8px 0}.sectionNote{font-size:12px;color:var(--muted);margin:-6px 0 12px}.bonusPos{color:#176f38;font-weight:900}.bonusNeg{color:#9e3127;font-weight:900}.error{background:#fff0ee;color:#9e3127;border:1px solid #efc8c2;padding:14px;border-radius:14px}.vehicleTitle{font-weight:850}.auditPayload{white-space:pre-wrap;word-break:break-word;font-size:12px;color:var(--muted);margin-top:6px}.tools{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.tools a{display:inline-flex;text-decoration:none;background:#e8e9e6;border-radius:10px;padding:10px 12px;font-weight:800}.tools a.primary{background:var(--y)}.discountEditor{display:grid;gap:10px}.discountEditor label{display:grid;gap:5px;font-weight:800}.discountEditor select,.discountEditor input{width:100%;padding:10px;border:1px solid var(--line);border-radius:9px;background:#fff}.discountQuick{display:flex;gap:7px;flex-wrap:wrap}.discountQuick button,.discountSave{border:0;border-radius:9px;padding:9px 12px;font-weight:850;cursor:pointer}.discountQuick button{background:#ecece8}.discountQuick button.active,.discountSave{background:var(--y)}.discountToggle{display:flex!important;grid-template-columns:auto 1fr;align-items:center;gap:9px}.discountToggle input{width:auto}.discountMessage{min-height:20px;font-size:12px}.discountState{padding:10px 12px;border-radius:11px;background:#f7f7f4}
@media(max-width:900px){.metrics{grid-template-columns:repeat(3,minmax(0,1fr))}.grid{grid-template-columns:1fr}.panel.wide{grid-column:auto}}@media(max-width:560px){.heroTop{display:block}.hero h1{font-size:26px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.row{display:block}.row .value{text-align:left;margin-top:3px}.topin{padding:0 10px}.back{padding:9px 10px}}
</style></head><body><header class="top"><div class="topin"><div class="brand">Профи<i>Спорт</i></div><a class="back" href="customers.php">← Клиенты</a></div></header>
<main><div id="root"><p>Загрузка карточки…</p></div></main>
<script>
let csrf='';const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const id=Number(new URLSearchParams(location.search).get('id')||0);
const fmt=n=>Number(n||0).toLocaleString('ru-RU');
const dt=v=>{if(!v)return '—';const d=new Date(String(v).replace(' ','T'));return Number.isNaN(d.getTime())?esc(v):d.toLocaleString('ru-RU')};
const d=v=>{if(!v)return '—';const x=new Date(String(v).slice(0,10)+'T00:00:00');return Number.isNaN(x.getTime())?esc(v):x.toLocaleDateString('ru-RU')};
const orderStatus={new:'Новый',confirmed:'Подтверждён',processing:'В работе',ready:'Готов к выдаче',completed:'Завершён',cancelled:'Отменён'};
const serviceStatus={new:'Новая',contacted:'Связались',accepted:'Принята',diagnostics:'Диагностика',repair:'Ремонт',ready:'Готово',completed:'Завершена',cancelled:'Отменена'};
const reviewStatus={pending:'На модерации',approved:'Опубликован',rejected:'Отклонён'};
const kindName={manual:'Ручная корректировка',order_earn:'Начисление за заказ',review_bonus:'Бонус за отзыв',reversal:'Отмена начисления',redeem:'Списание',expiry:'Сгорание',refund:'Возврат'};
function sourceName(value){return value==='store_qr'?'QR в магазине':value==='qr_and_account'?'QR + кабинет':'Сайт'}
function card(title,body,cls=''){return `<section class="panel ${cls}"><h2>${title}</h2>${body}</section>`}
async function auth(){const r=await fetch('../server/api.php?action=me',{cache:'no-store'});if(!r.ok){location.href='index.php';return false}const j=await r.json();csrf=j.csrf||'';return true}
function discountMarkup(j){
  const x=j.customer_discount||{enabled:false,percent_bp:0,group_key:null},groups=Array.isArray(j.discount_groups)?j.discount_groups:[];
  const pct=Number(x.percent_bp||0)/100;
  return `<div class="discountEditor"><div class="discountState"><b>${x.enabled?'Персональная скидка включена':'Персональная скидка выключена'}</b><div class="meta">${x.enabled?(pct.toLocaleString('ru-RU')+'% · '+(x.group_key?'только выбранная группа':'весь каталог')):'Клиент получает только общие правила Центра лояльности.'}</div></div><label class="discountToggle"><input id="discountEnabled" type="checkbox" ${x.enabled?'checked':''}><span>Включить персональную скидку</span></label><div class="discountQuick"><button type="button" data-discount-pct="5">5%</button><button type="button" data-discount-pct="7">7%</button><button type="button" data-discount-pct="10">10%</button><button type="button" data-discount-pct="15">15%</button></div><label>Размер скидки<input id="discountPercent" type="number" min="0" max="90" step="0.5" value="${pct||5}"></label><label>Область действия<select id="discountGroup"><option value="">Весь каталог</option>${groups.map(g=>`<option value="${esc(g.key)}" ${String(x.group_key||'')===String(g.key)?'selected':''}>${esc(g.name)} · ${(Number(g.percent_bp||0)/100).toLocaleString('ru-RU')}%</option>`).join('')}</select></label><label>Комментарий<input id="discountNote" maxlength="255" value="${esc(x.note||'')}" placeholder="Например: постоянный клиент"></label><button id="saveDiscount" class="discountSave" type="button">Сохранить скидку</button><div id="discountMessage" class="discountMessage"></div></div>`;
}
async function saveDiscount(){
  const enabled=$('#discountEnabled').checked,percent=Math.max(0,Math.min(90,Number($('#discountPercent').value)||0)),msg=$('#discountMessage'),button=$('#saveDiscount');
  button.disabled=true;msg.textContent='Сохраняю…';
  try{
    const r=await fetch('../api/customer-admin.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({action:'set_discount',customer_id:id,enabled,percent_bp:Math.round(percent*100),group_key:$('#discountGroup').value||null,note:$('#discountNote').value.trim()})});
    const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'save_failed');msg.innerHTML='<span class="ok">Персональная скидка сохранена.</span>';setTimeout(load,250);
  }catch(e){msg.innerHTML='<span class="err">Не удалось сохранить скидку.</span>';button.disabled=false}
}
function orderMarkup(x){const items=(x.items||[]).map(i=>`<li>${esc(i.title)} × ${fmt(i.quantity)} — ${fmt(i.line_total_rub)} ₽</li>`).join('');const hist=(x.history||[]).map(h=>`<span>${dt(h.created_at)} · ${esc(orderStatus[h.status]||h.status)}</span>`).join('');return `<article class="card"><h3>Заказ ${esc(x.order_number)}</h3><div class="chips"><span class="chip ${x.status==='completed'?'green':x.status==='cancelled'?'red':'yellow'}">${esc(orderStatus[x.status]||x.status)}</span><span class="chip">${dt(x.created_at)}</span><span class="chip">${esc(x.delivery_method||'')}</span></div><div class="money">${fmt(x.total_rub)} ₽</div>${x.pickup_store?`<div class="meta">Самовывоз: ${esc(x.pickup_store)}</div>`:''}${x.address?`<div class="meta">Адрес: ${esc(x.address)}</div>`:''}${items?`<ul class="items">${items}</ul>`:''}${hist?`<div class="timeline">${hist}</div>`:''}</article>`}
function vehicleMarkup(x){return `<article class="card"><div class="vehicleTitle">${esc(x.title)}</div><div class="chips"><span class="chip">${x.vehicle_type==='bicycle'?'Велосипед':'Самокат'}</span>${x.order_number?`<span class="chip">Заказ ${esc(x.order_number)}</span>`:''}</div><div class="meta">Покупка: ${dt(x.purchase_date||x.created_at)}</div></article>`}
function serviceMarkup(x){const hist=(x.history||[]).map(h=>`<span>${dt(h.created_at)} · ${esc(serviceStatus[h.status]||h.status)}</span>`).join('');return `<article class="card"><h3>${esc(x.request_number||('Заявка #'+x.id))}</h3><div class="chips"><span class="chip ${x.status==='completed'?'green':x.status==='cancelled'?'red':'yellow'}">${esc(serviceStatus[x.status]||x.status)}</span>${x.vehicle_title?`<span class="chip">${esc(x.vehicle_title)}</span>`:''}</div><div>${esc(x.problem||'')}</div>${hist?`<div class="timeline">${hist}</div>`:''}</article>`}
async function load(){
  if(id<1){root.innerHTML='<div class="error">Не указан клиент.</div>';return}
  const r=await fetch('../api/customer-admin.php?id='+id,{cache:'no-store'}),j=await r.json().catch(()=>({ok:false}));
  if(!r.ok||!j.ok){root.innerHTML='<div class="error">Не удалось открыть карточку клиента.</div>';return}
  const c=j.customer||{},name=[c.name,c.last_name].filter(Boolean).join(' ')||('Клиент #'+id);
  const vehicles=j.vehicles||[],services=j.service_requests||[],orders=j.orders||[],favorites=j.favorites||[],reviews=j.reviews||[],loyalty=j.loyalty||[],audit=j.audit||[];
  root.innerHTML=`<section class="hero"><div class="heroTop"><div><h1>${esc(name)}</h1><div class="muted">${esc(c.phone||'Телефон не указан')} · ${esc(c.email||'Email не указан')}</div><div class="tools"><a class="primary" href="customers.php">К списку клиентов</a><a href="orders.php">Заказы</a><a href="service.php">Мастерская</a></div></div><div><span class="status ${Number(c.is_active)?'ok':''}">${Number(c.is_active)?'Активный клиент':'Неактивный клиент'}</span></div></div><div class="metrics"><div class="metric"><b>${fmt(c.orders_count)}</b><span>заказов</span></div><div class="metric"><b>${fmt(vehicles.length)}</b><span>единиц техники</span></div><div class="metric"><b>${fmt(c.service_count)}</b><span>обращений в сервис</span></div><div class="metric"><b>${fmt(c.favorites_count)}</b><span>в избранном</span></div><div class="metric"><b>${fmt(c.reviews_count)}</b><span>отзывов</span></div><div class="metric"><b>${fmt(c.bonus_balance)}</b><span>бонусов</span></div></div></section>
  <div class="grid">
    ${card('Профиль',`<div class="rows"><div class="row"><span>Имя</span><span class="value">${esc(name)}</span></div><div class="row"><span>Телефон</span><span class="value">${esc(c.phone||'—')}</span></div><div class="row"><span>Email</span><span class="value">${esc(c.email||'—')}</span></div><div class="row"><span>Дата рождения</span><span class="value">${d(c.birth_date)}</span></div><div class="row"><span>Предпочитаемый магазин</span><span class="value">${esc(c.preferred_store||'Не выбран')}</span></div><div class="row"><span>Источник</span><span class="value">${esc(sourceName(c.registration_source))}</span></div><div class="row"><span>Личный кабинет</span><span class="value">${Number(c.has_account)?'Есть':'Нет'}</span></div><div class="row"><span>Регистрация</span><span class="value">${dt(c.created_at)}</span></div></div>`)}
    ${card('Персональная скидка',discountMarkup(j))}
    ${card('Бонусы',`<div class="money">${fmt(c.bonus_balance)} бонусов</div><div class="sectionNote">Программа сейчас ${j.loyalty_program?.enabled?'включена':'выключена'}. Полная история операций ниже.</div><div class="cards">${loyalty.length?loyalty.map(x=>`<article class="card"><div><span class="${Number(x.amount)>=0?'bonusPos':'bonusNeg'}">${Number(x.amount)>=0?'+':''}${fmt(x.amount)}</span> · ${esc(kindName[x.kind]||x.kind)}</div><div class="meta">${dt(x.created_at)}${x.note?' · '+esc(x.note):''}${x.expires_at?' · сгорание '+dt(x.expires_at):''}</div></article>`).join(''):'<div class="empty">Операций пока нет.</div>'}</div>`)}
    ${card('Моя техника',`<div class="cards">${vehicles.length?vehicles.map(vehicleMarkup).join(''):'<div class="empty">Завершённых покупок велосипеда или самоката пока нет.</div>'}</div>`)}
    ${card('Сервис',`<div class="cards">${services.length?services.map(serviceMarkup).join(''):'<div class="empty">Связанных обращений в мастерскую пока нет.</div>'}</div>`)}
    ${card('Заказы',`<div class="cards">${orders.length?orders.map(orderMarkup).join(''):'<div class="empty">Заказов пока нет.</div>'}</div>`,'wide')}
    ${card('Избранное',`<div class="cards">${favorites.length?favorites.map(x=>`<article class="card"><h3>${esc(x.name||('Товар #'+x.product_id))}</h3><div class="chips"><span class="chip">${fmt(x.price_rub)} ₽</span><span class="chip">${Number(x.is_active)&&Number(x.stock_qty)>0?'В наличии':'Недоступен'}</span></div><div class="meta">Добавлен: ${dt(x.saved_at)}</div></article>`).join(''):'<div class="empty">Избранное пусто.</div>'}</div>`)}
    ${card('Отзывы',`<div class="cards">${reviews.length?reviews.map(x=>`<article class="card"><h3>${esc(x.product_name||('Товар #'+x.product_id))}</h3><div class="chips"><span class="chip">${'★'.repeat(Math.max(0,Math.min(5,Number(x.rating)||0)))}</span><span class="chip">${esc(reviewStatus[x.status]||x.status)}</span>${Number(x.bonus_awarded)?'<span class="chip green">Бонус начислен</span>':''}</div><div>${esc(x.review_text||'')}</div><div class="meta">${dt(x.created_at)}</div></article>`).join(''):'<div class="empty">Отзывов пока нет.</div>'}</div>`)}
    ${card('История действий',`<div class="cards">${audit.length?audit.map(x=>`<article class="card"><h3>${esc(x.action)}</h3><div class="meta">${dt(x.created_at)} · ${esc(x.admin_username||'Система')}</div>${x.payload?`<div class="auditPayload">${esc(x.payload)}</div>`:''}</article>`).join(''):'<div class="empty">Административных действий по клиенту пока нет.</div>'}</div>`,'wide')}
  </div>`;
  document.querySelectorAll('[data-discount-pct]').forEach(b=>b.onclick=()=>{$('#discountPercent').value=b.dataset.discountPct;$('#discountEnabled').checked=true});
  $('#saveDiscount')?.addEventListener('click',saveDiscount);
}
(async()=>{if(await auth())load()})();
</script></body></html>
